# Option (a):
def push_fruit(FruitStack, Fruit):
    if Fruit['Price'] < 100:
        FruitStack.append(Fruit)

def pop_fruit(FruitStack):
    if not FruitStack:
        print('UNDERFLOW')
        return None
    return FruitStack.pop()

def display(FruitStack):
    if not FruitStack:
        print('EMPTY STACK')
    else:
        for i in range(len(FruitStack)-1, -1, -1):
            print(FruitStack[i])

# OR Option (b):
stack = []
for _ in range(10):
    num = int(input())
    if 100 <= num <= 999 and num % 2 == 0:
        stack.append(num)
while stack:
    print(stack.pop(), end=' ')

